using System;
using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using Extensions.Pack;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.Extensions.DependencyInjection;
using AspNetCore.MinimalApi.Sdk.CodeRules.Services;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("Services")]
    [TestClass]
    public class RJIT_CR_S_00003 : ServiceTestBase
    {
         [TestMethod]
        public void Each_Service_Should_Register_Have_To_Be_Called()
        {
            var missingRegistrationCalls = FindMissingRegistrationCalls().ToImmutableList();

            Assert.IsTrue(missingRegistrationCalls.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_S_00003

Your service registration in your code have to be called. Otherwise your application will not start. 
Findings {missingRegistrationCalls.Count}.{Environment.NewLine}{missingRegistrationCalls.Flatten(Environment.NewLine)}");
            
            IEnumerable<string> FindMissingRegistrationCalls()
            {
                var serviceWithRegistrations = from service in Services
                                               where service.Registration is not null
                                               select service;


                var statements = SyntaxTreesToAnalyze.SelectMany(c => c.Classes).SelectMany(c => c.Methods).SelectMany(m => m.Statements).ToImmutableList();

                foreach (var serviceWithRegistration in serviceWithRegistrations)
                {
                    foreach (var registrationMethod in serviceWithRegistration.Registration.Methods)
                    {
                        var missing = !statements.Any(statement => statement.Contains($".{registrationMethod.Name}"));
                        if (missing)
                        {
                            yield return $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Registration: 

{registrationMethod.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:       

services.{registrationMethod.Name}();
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
";
                        }
                    }
                }
            }
        }
    }
}
